// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line orders_tester.scxml:5
func (p *OrdersTesterPolicy) FirstEnabledTransition(state OrdersTesterState, event OrdersTesterEvent, engine *sce.Engine[OrdersTesterState, OrdersTesterEvent]) (sce.EnabledTransition[OrdersTesterState, sce.HistoryID], bool) {
	switch state {
	case OrdersTesterStateOrdering:
		if event == OrdersTesterEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if scetestprofile.Receives(p.sceTestContext, "sut", "order.placed", func(sceMessage sce_order_placed_match.Value) bool { return sce_order_placed_match.Matches(sceMessage, p.vLimit) }) {
				return sce.EnabledTransition[OrdersTesterState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfOrdersTester[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[OrdersTesterState, sce.HistoryID]{}, false
}

// TakeTransition takes a branch of the test component before the microstep
// exits any state (docs/SCE_TEST_PROFILE.md §4.4, P4 step 1, §12.3): it removes
// what the branch matched from the round's snapshot, writes its record in the
// test log, and holds a message its content reads in the payload field of its
// record's event (`Transition::native_take`). The policy is a sce.TransitionTaker.
func (p *OrdersTesterPolicy) TakeTransition(source OrdersTesterState, transitionIndex int, engine *sce.Engine[OrdersTesterState, OrdersTesterEvent]) {
	switch source {
	case OrdersTesterStateOrdering:
		switch transitionIndex {
		case 0:
			p.sceTestContext.Receive("sut")
		}
	}
}

